<?php
$base64 = "";
?>

<?php
ob_start();

error_reporting(E_ALL);
ini_set('display_errors',1);

date_default_timezone_set('Asia/Kolkata');

require_once('tcpdf/tcpdf.php');

$pdf = new TCPDF();
$pdf->SetPrintHeader(false);
$pdf->SetPrintFooter(false);
$pdf->AddPage();



$folder = "qr_images/";

if(!file_exists($folder)){
    mkdir($folder,0777,true);
}

// -------------------------------
// Decode Base64
// -------------------------------
$base64 = preg_replace('#^data:image/\w+;base64,#i', '', $base64);
$imageData = base64_decode($base64);

if($imageData === false){
    die("Invalid Base64 Data");
}

// -------------------------------
// File Save
// -------------------------------
$fileName = "qr_".date("YmdHis").".jpg";
$filePath = $folder.$fileName;

$result = file_put_contents($filePath, $imageData);

echo "<img src='".$filePath."' style='border:1px solid #ccc;padding:10px;' />";
die;

/* server path */
$img = "/var/www/starsaathi/public_html/SAP/dashboard/qr_images/qr_20260313093354.bmp";
$img = "/var/www/starsaathi/public_html/SAP/dashboard/qr_images/qr_20260313093354.bmp";

if(!file_exists($img)){
    die("Image not found: ".$img);
}

$html = '
<h2>HTML to PDF Image Test</h2>

<table border="1" cellpadding="5">
<tr>
<td>QR Image</td>
<td align="right">
<img src="'.$filePath.'" width="48" height="48" />
<!--<img src="images/star-pdf-logo.jpeg" width="50px" style="position:absolute;top:10px;left:10px;" />-->
</td>
</tr>
</table>
';

$pdf->writeHTML($html);

ob_end_clean();
$pdf->Output('html_test.pdf','I');
?>